from pathlib import Path
HERE=Path(__file__).resolve().parent

def load(name,file):
    spec=importlib.util.spec_from_file_location(name,HERE/file);m=importlib.util.module_from_spec(spec);sys.modules[name]=m;spec.loader.exec_module(m);return m
pre=load('preflight_v21','preflight.py');charts=load('charts_v21','generate_charts.py');modeler=load('model_v21','build_report_model.py');validator=load('validator_v21','validate_run.py');scorer=load('scorer_v21','score_geo.py');htmlr=load('html_v21','generate_report_html.py');docxr=load('docx_v21','generate_report_docx.py');pdfr=load('pdf_v21','generate_report_pdf.py')

def wcsv(p,fields,rows):
    with p.open('w',encoding='utf-8',newline='') as f:wr=csv.DictWriter(f,fieldnames=fields);wr.writeheader();wr.writerows(rows)
def rcsv(p):
    with p.open('r',encoding='utf-8-sig',newline='') as f:return list(csv.DictReader(f))
