    qf=['query_id','query_text','query_type','query_purpose','measurement_target','discovery_channel','discovery_round','semantic_theme','theme','region','city','exam','sampled_channel','sampled_at','status','notes'];qs=[];channels=['user-query','exam-vertical','institutional','platform','expert-ip','entity-alias']
